// 파일 책임: 화면 전체 진행 덮개. 등록소를 제공하고, 진행이 있으면 본문을 막고(inert·aria-busy) 가운데 진행 표시와 문구를 띄운다.
// 무엇이 진행 중인지는 등록(폼 저장·페이지 첫 조회)이, 문구는 프로젝트가 정한다. 덮개가 닫힐 때 잃은 포커스를 본문으로 돌린다
// (본문 DOM 안에서 마지막으로 포커스한 요소 → 사라졌으면 본문 첫 h1 → 그것도 없으면 본문 영역).
import type { ReactNode } from 'react';
import { BlockingProgressProvider, useBlockingProgressBinding } from '@boosterlab/web-kit/dialog';
import { Spinner } from './pending';

/** 종류별 주 문구와 보조 문구(없으면 그리지 않음). */
export interface BlockingProgressMessages {
  readonly loading: string;
  readonly create: string;
  readonly edit: string;
  readonly delete: string;
  readonly wait?: string;
}

/**
 * 앱 셸에 한 번 두는 덮개. children(앱 본문)은 진행 중 inert·aria-busy가 되어 클릭·포커스·낭독에서 빠진다.
 * 대화창(portal)은 children 밖이라 덮개 위에서 조작된다. 덮개 층은 CSS 변수 `--wk-blocking-layer`(기본은 키트 대화창 아래).
 * 상태 문구 영역(role=status)은 늘 있고 열릴 때 문구가 들어가 낭독기가 바뀜을 읽는다. 최소 표시 시간·지연은 없다.
 * `indicator`는 가운데 진행 표시를 프로젝트 모양으로 바꾼다(없으면 키트 원형 회전 표시). 덮개 전체가 낭독기에 숨겨져 있어(문구는 상태 영역이 읽는다) 표시는 그림만 맡고,
 * 움직임 줄이기 설정은 그 표시를 준 프로젝트가 맞춘다.
 */
export function BlockingProgress({
  messages,
  indicator,
  children,
}: {
  readonly messages: BlockingProgressMessages;
  readonly indicator?: ReactNode;
  readonly children: ReactNode;
}) {
  const binding = useBlockingProgressBinding();
  const { kind, open, contentRef, contentProps } = binding;
  return (
    <BlockingProgressProvider binding={binding}>
      <div
        ref={contentRef}
        className="wk-blocking-root"
        {...contentProps}
      >
        {children}
      </div>
      {open ? (
        <div className="wk-blocking" aria-hidden="true">
          <div className="wk-blocking-box">
            {indicator === undefined ? <Spinner large /> : indicator}
            <div className="wk-blocking-text">
              <p>{messages[kind!]}</p>
              {messages.wait === undefined ? null : <p>{messages.wait}</p>}
            </div>
          </div>
        </div>
      ) : null}
      <div role="status" aria-live="polite" aria-atomic="true" className="wk-blocking-status wk-visually-hidden">
        {open ? [messages[kind!], messages.wait].filter((text) => text !== undefined).join(' ') : ''}
      </div>
    </BlockingProgressProvider>
  );
}

// @vitest-environment jsdom
// 파일 책임: 덮개 자체와 실제 함께 설치된 기능의 조합만 소비 복사본으로 검사한다.
import { BlockingProgress } from '../ui/blocking-progress';
import { ConfirmDialog } from '../ui/dialog';
import { checkProgressConformance } from '@boosterlab/web-kit/testing/unit/blocking-progress';
import type { checkFormProgressConformance as FormProgressCheck } from '@boosterlab/web-kit/testing/unit/combinations';
import installation from '../../../../../registry-installation.json';
const target = { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit };
checkProgressConformance({ BlockingProgress, ConfirmDialog }, target);
const names = new Set(installation.items.map((item) => item.name));
if (names.has('form')) {
  const forms = import.meta.glob('../form/ui.tsx');
  const load = forms['../form/ui.tsx'];
  if (!load) throw new Error('form 설치 기록에 맞는 소비 복사본 없음');
  const module = await load() as { Form: Parameters<typeof FormProgressCheck>[0]['Form'] };
  const { Form } = module;
  const { checkFormProgressConformance } = await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkFormProgressConformance({ Form, BlockingProgress }, target);
}
if (names.has('list')) {
  const { checkListProgressConformance } = await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkListProgressConformance({ BlockingProgress }, target);
}
if (names.has('record')) {
  const { checkRecordProgressConformance } = await import('@boosterlab/web-kit/testing/unit/combinations');
  await checkRecordProgressConformance({ BlockingProgress }, target);
}

// 파일 책임: 설치한 덮개·대화창과 선택적인 폼 복사본으로 브라우저 화면을 만든다.
import { createRoot } from 'react-dom/client';
import { createProgressFeatureConformancePage } from '@boosterlab/web-kit/testing/fixtures/progress';
import { BlockingProgress } from '../ui/blocking-progress';
import { Dialog } from '../ui/dialog';
import type { createFormProgressConformancePage as FormProgressPage } from '@boosterlab/web-kit/testing/fixtures/combinations';
import installation from '../../../../../registry-installation.json';
import '../ui/styles.css';
let Page = createProgressFeatureConformancePage({ BlockingProgress, Dialog });
if (new URLSearchParams(location.search).get('mode') === 'error' && installation.items.some((item) => item.name === 'form')) {
  const forms = import.meta.glob('../form/ui.tsx');
  const load = forms['../form/ui.tsx'];
  if (!load) throw new Error('form 설치 기록에 맞는 소비 복사본 없음');
  const { Form } = await load() as { Form: Parameters<typeof FormProgressPage>[0]['Form'] };
  const { createFormProgressConformancePage } = await import('@boosterlab/web-kit/testing/fixtures/combinations');
  Page = createFormProgressConformancePage({ Form, BlockingProgress });
}
createRoot(document.getElementById('root')!).render(<Page />);

// 파일 책임: 덮개 자체의 브라우저 검사와 설치한 폼 조합만 등록한다.
import { checkProgressFeatureBrowser, checkFormProgressBrowser } from '@boosterlab/web-kit/testing/browser';
import installation from '../../../registry-installation.json' with { type: 'json' };
const options = { url: '/web-kit-checks/blocking-progress.html', target: { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit } };
checkProgressFeatureBrowser(options);
if (installation.items.some((item) => item.name === 'form')) checkFormProgressBrowser(options);
